// ── IP helpers ─────────────────────────────────────────────────────────────
function ipv6Prefix(ip) {
  const halves = ip.split('::');
  const left   = halves[0] ? halves[0].split(':') : [];
  const right  = halves[1] ? halves[1].split(':') : [];
  const fill   = 8 - left.length - right.length;
  const full   = [...left, ...Array(fill).fill('0'), ...right];
  return full.slice(0, 4).join(':');
}

// ── Helpers ─────────────────────────────────────────────────────────────────
function html(body, status = 200) {
  return new Response(body, { status, headers: { 'Content-Type': 'text/html; charset=utf-8', 'X-Content-Type-Options': 'nosniff' } });
}

function serveIcon(b64) {
  const raw   = b64.split(',')[1];
  const bin   = atob(raw);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return new Response(bytes, { headers: { 'Content-Type': 'image/png', 'Cache-Control': 'public, max-age=604800' } });
}

function err(status, message) {
  return cors(Response.json({ error: message }, { status }));
}

function notFound() { return html(deletedPage('Not Found', 'This page does not exist.'), 404); }
function gone()     { return html(deletedPage('Page Expired', 'This page has expired or been deleted.'), 410); }

function cors(response) {
  const r = new Response(response.body, response);
  r.headers.set('Access-Control-Allow-Origin', '*');
  r.headers.set('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  r.headers.set('Access-Control-Allow-Headers', 'Content-Type');
  return r;
}

function toB64(bytes) {
  let str = '';
  for (let i = 0; i < bytes.length; i += 8192)
    str += String.fromCharCode(...bytes.subarray(i, i + 8192));
  return btoa(str);
}
